// fv_ad_vf_fmt_info -- ad_vf_fmt_info equals the table of tools/fmtmodel.py info() (generated by
// tools/gen_fetch_vectors.py into fmt_info_ref.vh) for every {vkfmt, legacy} (256 x 16).
// Combinational: inputs are anyconst.
module fv_ad_vf_fmt_info (input wire clk);
    (* anyconst *) reg [7:0] ref_vk;
    (* anyconst *) reg [3:0] ref_lg;
    reg [10:0] ref_info;
`include "fmt_info_ref.vh"
    wire [4:0] size; wire [2:0] ncomp, kind;
    ad_vf_fmt_info dut (.vkfmt(ref_vk), .legacy(ref_lg), .size(size), .ncomp(ncomp), .kind(kind));
    always @(*) begin
        a_size:  assert (size  == ref_info[10:6]);
        a_ncomp: assert (ncomp == ref_info[5:3]);
        a_kind:  assert (kind  == ref_info[2:0]);
        c_12:    cover (size == 5'd12 && ref_vk != 0);
    end
endmodule
